document.addEventListener('DOMContentLoaded',()=>{const days=document.querySelector('.route-days');if(!days)return;days.querySelectorAll('div').forEach(day=>{const remove=document.createElement('button');remove.className='route-remove';remove.textContent='Remover';remove.onclick=()=>{day.remove();refresh()};day.appendChild(remove)});const share=document.createElement('button');share.className='route-share';share.textContent='Copiar roteiro';share.onclick=async()=>{const items=[...days.querySelectorAll('div')].map(x=>x.querySelector('b').textContent+' — '+x.querySelector('strong').textContent).join('\n');try{await navigator.clipboard.writeText('Meu roteiro em Angra:\n'+items);share.textContent='Roteiro copiado'}catch{share.textContent='Selecione o roteiro para copiar'}setTimeout(()=>share.textContent='Copiar roteiro',1800)};days.parentElement.appendChild(share);function refresh(){if(!days.children.length){days.innerHTML='<p class="route-empty">Seu roteiro está vazio. Continue dando match nos destinos.</p>';share.remove()}}const s=document.createElement('style');s.textContent='.route-remove{border:0;background:transparent;color:#8a9d9d;font-size:10px;padding:2px 0;cursor:pointer}.route-share{width:100%;margin-top:10px;border:1px solid #b7d3cd;background:transparent;color:#142b3a;border-radius:10px;padding:10px;font-weight:700;font-size:12px;cursor:pointer}.route-empty{font-size:12px;color:#66808b}';document.head.appendChild(s)});
